(6378629, 945226, 54645, '<td valign="top">Alien ships have come to take a cat named Pointy. Baghead Ben</td>', 'Alien ships have come to take a cat named Pointy. Baghead Ben', '2011-04-08 02:26:36.000000', NULL, 1),
(6378635, 945203, 54645, '<td valign="top">captivating</td>', 'captivating', '2011-04-08 02:28:02.000000', NULL, 1),
(6378636, 942732, 54645, '<td valign="top">What I find most endearing are the repetition of lines in of all angles. Reflections, rails, masts, rain, and clouds. All emphasized by your tonal rendition. Baghead Ben</td>', 'What I find most endearing are the repetition of lines in of all angles. Reflections, rails, masts, rain, and clouds. All emphasized by your tonal rendition. Baghead Ben', '2011-04-08 02:28:04.000000', NULL, 1),
(6378639, 945058, 54645, '<td valign="top">A tangled line of beauty. Spectacular imagery and manipulation of emotions. Well done.</td>', 'A tangled line of beauty. Spectacular imagery and manipulation of emotions. Well done.', '2011-04-08 02:29:51.000000', NULL, 1),
(6378644, 942732, 30214, '<td valign="top">lovely image, very atmospheric. great contrast between heavy horizontal skies and precariously thin but defiantly upright boat masts. Maybe I would go a little easier on the grain in the sky, or maybe not, hard to say without comparing. And I like your signature toning :). <br/> <br/>I find it very amusing that you used this term for the title. I used it a lot in my studies in granular physics :)</td>', 'lovely image, very atmospheric. great contrast between heavy horizontal skies and precariously thin but defiantly upright boat masts. Maybe I would go a little easier on the grain in the sky, or maybe not, hard to say without comparing. And I like your signature toning :).  I find it very amusing that you used this term for the title. I used it a lot in my studies in granular physics :)', '2011-04-08 02:33:30.000000', NULL, 1),
(6378648, 944750, 30214, '<td valign="top">ah, life on a river! these black segments, the pole and the foreground man make very interesting framing within a frame.</td>', 'ah, life on a river! these black segments, the pole and the foreground man make very interesting framing within a frame.', '2011-04-08 02:36:54.000000', NULL, 1),
(6378650, 945098, 30214, '<td valign="top">interesting idea about all this red, but the background red appears just painted over... and that let the image down, IMO</td>', 'interesting idea about all this red, but the background red appears just painted over... and that let the image down, IMO', '2011-04-08 02:38:42.000000', NULL, 1),
(6378658, 945082, 30214, '<td valign="top">it is a nice, moody scene, if not for the halos around the tree trunks</td>', 'it is a nice, moody scene, if not for the halos around the tree trunks', '2011-04-08 02:41:36.000000', NULL, 1),
(6378663, 945005, 30214, '<td valign="top">Interesting! God, Eve, and the Tree all in one :) I wish you used a greater DOF to get apple in focus</td>', 'Interesting! God, Eve, and the Tree all in one :) I wish you used a greater DOF to get apple in focus', '2011-04-08 02:43:47.000000', NULL, 1),
(6378670, 943485, 30214, '<td valign="top">amazing how weightlessness of the girl and her dress are captured, she is flying, liberated. And wonderful pastel tones and texture. cheers - Lev</td>', 'amazing how weightlessness of the girl and her dress are captured, she is flying, liberated. And wonderful pastel tones and texture. cheers - Lev', '2011-04-08 02:49:14.000000', NULL, 1),
