(6378859, 945187, 113156, '<td valign="top">This is really nice and definitely fine art to me.</td>', 'This is really nice and definitely fine art to me.', '2011-04-08 08:22:12.000000', NULL, 1),
(6378860, 945217, 113156, '<td valign="top">Beautiful and natural looking, love the wooden backdrop.</td>', 'Beautiful and natural looking, love the wooden backdrop.', '2011-04-08 08:24:00.000000', NULL, 1),
(6378861, 945025, 113156, '<td valign="top">Umbrellas are such mundane and marvelous things, great photo and title, we are all a bit like that.</td>', 'Umbrellas are such mundane and marvelous things, great photo and title, we are all a bit like that.', '2011-04-08 08:25:45.000000', NULL, 1),
(6378863, 944747, 113156, '<td valign="top">minimalistic and intriguing , very nice.</td>', 'minimalistic and intriguing , very nice.', '2011-04-08 08:27:50.000000', NULL, 1),
(6378864, 945241, 113156, '<td valign="top">this is nothing special, which makes this really special.</td>', 'this is nothing special, which makes this really special.', '2011-04-08 08:30:14.000000', NULL, 1),
(6378866, 945058, 113156, '<td valign="top">wonderfully done.</td>', 'wonderfully done.', '2011-04-08 08:37:55.000000', NULL, 1),
(6378867, 944985, 113156, '<td valign="top">very effective and great idea, should do well.</td>', 'very effective and great idea, should do well.', '2011-04-08 08:40:20.000000', NULL, 1),
(6378877, 944333, 11854, '<td valign="top">This is so compelling, I can''t help returning to it over and over. The mix of buried boat with the snow topping is so reminiscent of a coffin on it''s way into the ground. The lostness we feel upon a death that is close to us. 10</td>', 'This is so compelling, I can''t help returning to it over and over. The mix of buried boat with the snow topping is so reminiscent of a coffin on it''s way into the ground. The lostness we feel upon a death that is close to us. 10', '2011-04-08 09:05:48.000000', NULL, 1),
(6378878, 944832, 11854, '<td valign="top">It seems 3 of my top 4 picks deal with death. It''s a fascinating subject, especially in art. Drowning is always portrayed as so peaceful, but it''s not. From what I understand it''s very painful. But we all want our illusions so we''ll keep it this way. Beautifully done! 10</td>', 'It seems 3 of my top 4 picks deal with death. It''s a fascinating subject, especially in art. Drowning is always portrayed as so peaceful, but it''s not. From what I understand it''s very painful. But we all want our illusions so we''ll keep it this way. Beautifully done! 10', '2011-04-08 09:06:48.000000', NULL, 1),
(6378879, 943621, 11854, '<td valign="top">So very powerful. Such a moving tribute to a great tragedy. The expression of fear in the eyes, the distortion of the face as her world ends makes this terrifying to see. But we are compelled to look to tragedy, and be thankful it wasn''t happening to us. 10</td>', 'So very powerful. Such a moving tribute to a great tragedy. The expression of fear in the eyes, the distortion of the face as her world ends makes this terrifying to see. But we are compelled to look to tragedy, and be thankful it wasn''t happening to us. 10', '2011-04-08 09:07:27.000000', NULL, 1),
(6378880, 944059, 108069, '<td valign="top">Wow. This is something else. Incredibly creative, interesting story, a couple lifetimes of effort, and perfectly executed. This is quite a piece of work.</td>', 'Wow. This is something else. Incredibly creative, interesting story, a couple lifetimes of effort, and perfectly executed. This is quite a piece of work.', '2011-04-08 09:07:58.000000', NULL, 1),
(6378884, 944059, 11854, '<td valign="top">So wonderfully quirky! Love the colors, the processing, the texture, the Freddy Kruger type character peeking out the window, the story, and especially that tulip growing out of the wall! Awesome work! 10</td>', 'So wonderfully quirky! Love the colors, the processing, the texture, the Freddy Kruger type character peeking out the window, the story, and especially that tulip growing out of the wall! Awesome work! 10', '2011-04-08 09:15:41.000000', NULL, 1),
(6378886, 944621, 108069, '<td valign="top">Beautiful image. I don''t dare say I have a box that defines what fine arts is to me, but this speaks volumes. I''m going to give this a 10, but don''t be surprised if you lose that 10 at rollover, as I''ll likely just still be here staring at it, without voting on the required 20%.</td>', 'Beautiful image. I don''t dare say I have a box that defines what fine arts is to me, but this speaks volumes. I''m going to give this a 10, but don''t be surprised if you lose that 10 at rollover, as I''ll likely just still be here staring at it, without voting on the required 20%.', '2011-04-08 09:18:27.000000', NULL, 1),
(6378889, 944649, 113156, '<td valign="top">Very beautifully done, the colors are scrumptious.</td>', 'Very beautifully done, the colors are scrumptious.', '2011-04-08 09:21:34.000000', NULL, 1),
