(6379191, 945170, 91360, '<td valign="top">love this! can definately decorate my living room. 10.</td>', 'love this! can definately decorate my living room. 10.', '2011-04-08 12:12:56.000000', NULL, 1),
(6379192, 945024, 118396, '<td valign="top">Definitely a unique shot - I can see the Fine Arts element.  The colors and the processing are really nice.  My only beef would be for the model to PULL HIS PANTS UP!  Goodness!  Don''t people realize that this ''fad'' started in prisons as a sign that you were available for anyone who wants to accost you?  Sorry for the rant, just a real pet peeve with me.  Now that I''m off my soap box - nicely done photograph. (not voting)</td>', 'Definitely a unique shot - I can see the Fine Arts element.  The colors and the processing are really nice.  My only beef would be for the model to PULL HIS PANTS UP!  Goodness!  Don''t people realize that this ''fad'' started in prisons as a sign that you were available for anyone who wants to accost you?  Sorry for the rant, just a real pet peeve with me.  Now that I''m off my soap box - nicely done photograph. (not voting)', '2011-04-08 12:14:22.000000', NULL, 1),
(6379193, 945005, 91360, '<td valign="top">the snake should have been on the apple..anyway uts great.</td>', 'the snake should have been on the apple..anyway uts great.', '2011-04-08 12:15:33.000000', NULL, 1),
(6379194, 945200, 118396, '<td valign="top">Normally I prefer crisp, highly-focused images, but this is really nice.  Reminds me of spring after a warm rain.  :)</td>', 'Normally I prefer crisp, highly-focused images, but this is really nice.  Reminds me of spring after a warm rain.  :)', '2011-04-08 12:15:47.000000', NULL, 1),
(6379195, 945123, 118396, '<td valign="top">That is super cool.  Well done.</td>', 'That is super cool.  Well done.', '2011-04-08 12:17:05.000000', NULL, 1),
(6379196, 945199, 118396, '<td valign="top">I love how the swirl makes it look like a flower.  Really neat image!</td>', 'I love how the swirl makes it look like a flower.  Really neat image!', '2011-04-08 12:17:33.000000', NULL, 1),
(6379198, 945207, 118396, '<td valign="top">I like the lighting and the layout.  My only quirk would be to use green onions instead of red.  I think they would be the more likely choice by a chef and would blend with the earthy colors of the browns better.  The focus on the noodles is great!</td>', 'I like the lighting and the layout.  My only quirk would be to use green onions instead of red.  I think they would be the more likely choice by a chef and would blend with the earthy colors of the browns better.  The focus on the noodles is great!', '2011-04-08 12:21:19.000000', NULL, 1),
(6379199, 943621, 118396, '<td valign="top">Wow.  Great job!</td>', 'Wow.  Great job!', '2011-04-08 12:21:35.000000', NULL, 1),
(6379200, 945156, 118396, '<td valign="top">This makes me want to jump in my car and drive to the beach RIGHT NOW!  I love the DOF and colors.</td>', 'This makes me want to jump in my car and drive to the beach RIGHT NOW!  I love the DOF and colors.', '2011-04-08 12:25:01.000000', NULL, 1),
(6379205, 942573, 118396, '<td valign="top">I really dig the hearts about her head and the soft edges of the focus.  What would have put it over the top for me is if you had cleaned up the edges of the wind-up key, maybe even painting it silver.  Otherwise, great concept and really neat shot!</td>', 'I really dig the hearts about her head and the soft edges of the focus.  What would have put it over the top for me is if you had cleaned up the edges of the wind-up key, maybe even painting it silver.  Otherwise, great concept and really neat shot!', '2011-04-08 12:27:14.000000', NULL, 1),
(6379206, 944649, 118396, '<td valign="top">Love the paint effects.  Beautiful!</td>', 'Love the paint effects.  Beautiful!', '2011-04-08 12:27:55.000000', NULL, 1),
(6379211, 945101, 97760, '<td valign="top">10 !!! - But I''m not sure how many person will know that you are talking about Greek''s mother nature Goddess... :)</td>', '10 !!! - But I''m not sure how many person will know that you are talking about Greek''s mother nature Goddess... :)', '2011-04-08 12:35:12.000000', NULL, 1),
(6379217, 945171, 97760, '<td valign="top">Dammit,  that''s so original!</td>', 'Dammit,  that''s so original!', '2011-04-08 12:38:41.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6379244, 945250, 113156, '<td valign="top">Love the movement here, is he doing his claws?, very nice photo and it fits the challenge well.</td>', 'Love the movement here, is he doing his claws?, very nice photo and it fits the challenge well.', '2011-04-08 13:06:55.000000', NULL, 1),
