(6379252, 945111, 113156, '<td valign="top">Very weird indeed, we can even see the underground sign behind, brilliant.  8</td>', 'Very weird indeed, we can even see the underground sign behind, brilliant.  8', '2011-04-08 13:13:25.000000', NULL, 1),
