(6379274, 945099, 129091, '<td valign="top">Lovely image...Nice background, lighting and texture on the flowers.  You nailed it!</td>', 'Lovely image...Nice background, lighting and texture on the flowers.  You nailed it!', '2011-04-08 13:28:10.000000', NULL, 1),
(6379275, 945217, 129091, '<td valign="top">Fantastic image...one of the few who nailed the challenge!  One of my favs...10</td>', 'Fantastic image...one of the few who nailed the challenge!  One of my favs...10', '2011-04-08 13:28:25.000000', NULL, 1),
(6379277, 943177, 129091, '<td valign="top">Beautiful work!  I would hang this on my wall.  10</td>', 'Beautiful work!  I would hang this on my wall.  10', '2011-04-08 13:28:34.000000', NULL, 1),
(6379278, 945132, 129091, '<td valign="top">Fantastic image!  You nailed it.</td>', 'Fantastic image!  You nailed it.', '2011-04-08 13:28:39.000000', NULL, 1),
(6379279, 945197, 129091, '<td valign="top">Very nice image!</td>', 'Very nice image!', '2011-04-08 13:28:42.000000', NULL, 1),
(6379280, 944747, 129091, '<td valign="top">Simplistic but very nice!  One of my favorites.</td>', 'Simplistic but very nice!  One of my favorites.', '2011-04-08 13:29:01.000000', NULL, 1),
(6379281, 944699, 129091, '<td valign="top">Lovely image, light, colors, and texture.  I would not have minded if you filled the entire frame...that is just a personal preference of mine, but regardless your image is good!</td>', 'Lovely image, light, colors, and texture.  I would not have minded if you filled the entire frame...that is just a personal preference of mine, but regardless your image is good!', '2011-04-08 13:30:10.000000', NULL, 1),
(6379283, 945133, 129091, '<td valign="top">Lovely image!  Nice soft tones.</td>', 'Lovely image!  Nice soft tones.', '2011-04-08 13:30:55.000000', NULL, 1),
(6379284, 945130, 129091, '<td valign="top">Nice work!</td>', 'Nice work!', '2011-04-08 13:31:17.000000', NULL, 1),
(6379285, 944059, 129091, '<td valign="top">Great work!  And very interesting image.</td>', 'Great work!  And very interesting image.', '2011-04-08 13:31:43.000000', NULL, 1),
(6379288, 944486, 129091, '<td valign="top">I''m not a big fan of out of focus images, but I like this...the bokeh is beautiful.  One distracting element for me is the highlighted leaf going across the image.  Regardless I like and I gave you an 8.</td>', 'I''m not a big fan of out of focus images, but I like this...the bokeh is beautiful.  One distracting element for me is the highlighted leaf going across the image.  Regardless I like and I gave you an 8.', '2011-04-08 13:33:04.000000', NULL, 1),
(6379290, 944320, 129091, '<td valign="top">Beautiful image, I love the moody feel it has.  I would like to see it less centered. Great job on the background.  Well done!</td>', 'Beautiful image, I love the moody feel it has.  I would like to see it less centered. Great job on the background.  Well done!', '2011-04-08 13:34:01.000000', NULL, 1),
(6379291, 944232, 129091, '<td valign="top">Nice composition, and I love the toning.  You have captured fine art!</td>', 'Nice composition, and I love the toning.  You have captured fine art!', '2011-04-08 13:34:34.000000', NULL, 1),
(6379328, 945182, 50695, '<td valign="top">this smells funny</td>', 'this smells funny', '2011-04-08 13:53:01.000000', NULL, 1),
(6379331, 945201, 100831, '<td valign="top">lovely movement and the greys are quite calming.  I don''t really get how the title relates but it doesn''t matter. 8</td>', 'lovely movement and the greys are quite calming.  I don''t really get how the title relates but it doesn''t matter. 8', '2011-04-08 13:54:51.000000', NULL, 1),
(6379335, 944054, 100831, '<td valign="top">sillhouette and bokeh - what a lovely chance for rumination.</td>', 'sillhouette and bokeh - what a lovely chance for rumination.', '2011-04-08 13:56:08.000000', NULL, 1),
(6379339, 942732, 50695, '<td valign="top">a lower ISO could help reduce noise</td>', 'a lower ISO could help reduce noise', '2011-04-08 14:01:15.000000', NULL, 1),
(6379341, 943485, 50695, '<td valign="top">a faster shutter speed will allow you to capture more detail</td>', 'a faster shutter speed will allow you to capture more detail', '2011-04-08 14:02:26.000000', NULL, 1),
(6379345, 945163, 50695, '<td valign="top">If you''re going to wear a suit like that, you should have your tailor adjust it first.</td>', 'If you''re going to wear a suit like that, you should have your tailor adjust it first.', '2011-04-08 14:03:56.000000', NULL, 1),
(6379360, 945176, 30712, '<td valign="top">I just want to keep looking at this image.  The shapes and colours are just superb.</td>', 'I just want to keep looking at this image.  The shapes and colours are just superb.', '2011-04-08 14:20:08.000000', NULL, 1),
