(6379418, 942732, 57447, '<td valign="top">This looks familiar to me, maybe not.  Nice work.</td>', 'This looks familiar to me, maybe not.  Nice work.', '2011-04-08 15:08:24.000000', NULL, 1),
(6379419, 945058, 50641, '<td valign="top">and how many toes?</td>', 'and how many toes?', '2011-04-08 15:09:02.000000', NULL, 1),
(6379456, 943485, 74559, '<td valign="top">This is gorgeous!</td>', 'This is gorgeous!', '2011-04-08 16:18:19.000000', NULL, 1),
(6379459, 944621, 129195, '<td valign="top">My favorite in the challenge by far. Great work! - 10.</td>', 'My favorite in the challenge by far. Great work! - 10.', '2011-04-08 16:22:17.000000', NULL, 1),
(6379461, 944585, 129195, '<td valign="top">Very cool! 9</td>', 'Very cool! 9', '2011-04-08 16:23:12.000000', NULL, 1),
