(6380714, 945215, 44877, '<td valign="top">Just brilliant. This has to land on the front page.</td>', 'Just brilliant. This has to land on the front page.', '2011-04-09 18:24:33.000000', NULL, 1),
(6380716, 944585, 121916, '<td valign="top">Excellent use of lines and curves in this.  The tones are magnificent, and the whites are handled to perfection.  This I would hang on a wall!</td>', 'Excellent use of lines and curves in this.  The tones are magnificent, and the whites are handled to perfection.  This I would hang on a wall!', '2011-04-09 18:41:33.000000', NULL, 1),
(6380726, 945182, 70661, '<td valign="top">I love shadows. The texture is great. The weeds really add to it.</td>', 'I love shadows. The texture is great. The weeds really add to it.', '2011-04-09 18:53:14.000000', NULL, 1),
(6380818, 945024, 54645, '<td valign="top">More body ink than hair! Quirky.</td>', 'More body ink than hair! Quirky.', '2011-04-09 21:29:29.000000', NULL, 1),
