(6381139, 945082, 114225, '<td valign="top">Very cool. The high contrast, gritty feel works well with this subject.</td>', 'Very cool. The high contrast, gritty feel works well with this subject.', '2011-04-10 10:37:30.000000', NULL, 1),
(6381140, 943177, 114225, '<td valign="top">Gorgeous scene. I really enjoy how the greens are coming up through the browns.</td>', 'Gorgeous scene. I really enjoy how the greens are coming up through the browns.', '2011-04-10 10:42:19.000000', NULL, 1),
