(6381144, 945176, 35545, '<td valign="top">Great colors and textures.</td>', 'Great colors and textures.', '2011-04-10 10:45:48.000000', NULL, 1),
(6381146, 945217, 114225, '<td valign="top">Excellent job with the textures in this photo</td>', 'Excellent job with the textures in this photo', '2011-04-10 10:48:51.000000', NULL, 1),
