(6381157, 945005, 114225, '<td valign="top">What amazing tonality to this photo.</td>', 'What amazing tonality to this photo.', '2011-04-10 11:05:16.000000', NULL, 1),
(6381164, 942652, 114225, '<td valign="top">Nice take on the bent paper shot. I was getting bored this these shots as they were all the same, but this one stands out. Not just because of the color, but the composition as well.</td>', 'Nice take on the bent paper shot. I was getting bored this these shots as they were all the same, but this one stands out. Not just because of the color, but the composition as well.', '2011-04-10 11:12:20.000000', NULL, 1),
(6381176, 945147, 129195, '<td valign="top">This is hauntingly beautiful. I can''t stop looking at it. Great job.</td>', 'This is hauntingly beautiful. I can''t stop looking at it. Great job.', '2011-04-10 11:24:06.000000', NULL, 1),
