INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6381186, 944663, 101668, '<td valign="top">lovely image.</td>', 'lovely image.', '2011-04-10 11:34:19.000000', NULL, 1),
(6381188, 944050, 101668, '<td valign="top">Excellent. I absolutely love this.</td>', 'Excellent. I absolutely love this.', '2011-04-10 11:40:40.000000', NULL, 1),
(6381203, 944747, 124982, '<td valign="top">Such a unique image. It could be a plant on wall, or an aerial view of a tree in a barren landscape. Just love the lengthy shadow cast!</td>', 'Such a unique image. It could be a plant on wall, or an aerial view of a tree in a barren landscape. Just love the lengthy shadow cast!', '2011-04-10 11:51:33.000000', NULL, 1),
(6381204, 945197, 101668, '<td valign="top">brilliant</td>', 'brilliant', '2011-04-10 11:51:38.000000', NULL, 1),
(6381206, 945179, 124982, '<td valign="top">Just a really cool shot filled with textures, tones and lots of details. I think I would''ve preferred a larger depth of field though..don''t feel like the narrow area of focus helps this particular image.</td>', 'Just a really cool shot filled with textures, tones and lots of details. I think I would''ve preferred a larger depth of field though..don''t feel like the narrow area of focus helps this particular image.', '2011-04-10 11:53:38.000000', NULL, 1),
(6381207, 944502, 124982, '<td valign="top">Interesting image. At first glance I thought this was a river...and then I noticed the hiker. Lovely blur and strong contrast with the post-processing. One particular aspect that works for this is the cropped hiker. Normally this would be a no-no for me, but it totally works in this image. Very nice!</td>', 'Interesting image. At first glance I thought this was a river...and then I noticed the hiker. Lovely blur and strong contrast with the post-processing. One particular aspect that works for this is the cropped hiker. Normally this would be a no-no for me, but it totally works in this image. Very nice!', '2011-04-10 11:55:18.000000', NULL, 1),
(6381208, 945248, 124982, '<td valign="top">So calm and peaceful. Wish I was there! Love the mirror reflection on the water.</td>', 'So calm and peaceful. Wish I was there! Love the mirror reflection on the water.', '2011-04-10 11:56:10.000000', NULL, 1),
(6381209, 944585, 124982, '<td valign="top">Such a unique image! Curious to know what this is! Paper? Plants? Something else? Very mysterious!</td>', 'Such a unique image! Curious to know what this is! Paper? Plants? Something else? Very mysterious!', '2011-04-10 11:57:46.000000', NULL, 1),
(6381210, 944960, 124982, '<td valign="top">Very Alice in Wonderland!</td>', 'Very Alice in Wonderland!', '2011-04-10 11:58:14.000000', NULL, 1),
(6381213, 945082, 124982, '<td valign="top">Really like this composition - such interesting trees, very bizarre arrangement!!  Only thing that doesn''t appeal to me is the clouds -- something about the processing makes them look pixelated and artifacty.</td>', 'Really like this composition - such interesting trees, very bizarre arrangement!!  Only thing that doesn''t appeal to me is the clouds -- something about the processing makes them look pixelated and artifacty.', '2011-04-10 12:00:58.000000', NULL, 1),
(6381215, 945245, 124982, '<td valign="top">Such a bizarre image!! Reminds me of something out of Monty Python!</td>', 'Such a bizarre image!! Reminds me of something out of Monty Python!', '2011-04-10 12:02:40.000000', NULL, 1),
(6381216, 945255, 129091, '<td valign="top">Interesting Idea!</td>', 'Interesting Idea!', '2011-04-10 12:05:53.000000', NULL, 1),
(6381217, 944983, 129091, '<td valign="top">Haunting image!  I like the title.</td>', 'Haunting image!  I like the title.', '2011-04-10 12:06:57.000000', NULL, 1),
(6381218, 945151, 129091, '<td valign="top">I love the color blends and texture, but for me this does not feel like fine art.  Still nicely composed.</td>', 'I love the color blends and texture, but for me this does not feel like fine art.  Still nicely composed.', '2011-04-10 12:07:50.000000', NULL, 1),
(6381220, 945064, 129091, '<td valign="top">I love IR and you picked up some great tone.  Feels surreal like most IR should.  IMO I would like to have seen more of the tree and sky and less of the foreground.  The tree has something special going on.</td>', 'I love IR and you picked up some great tone.  Feels surreal like most IR should.  IMO I would like to have seen more of the tree and sky and less of the foreground.  The tree has something special going on.', '2011-04-10 12:09:44.000000', NULL, 1),
(6381222, 945068, 129091, '<td valign="top">Nice creativity!</td>', 'Nice creativity!', '2011-04-10 12:10:04.000000', NULL, 1),
(6381225, 945014, 129091, '<td valign="top">Nice color and sharp lines.  For me I would have liked to see maybe a few more in the composition, just enough to make it more abstract. What I do like is the cleanness of the image.  Good job!</td>', 'Nice color and sharp lines.  For me I would have liked to see maybe a few more in the composition, just enough to make it more abstract. What I do like is the cleanness of the image.  Good job!', '2011-04-10 12:11:59.000000', NULL, 1),
(6381227, 943629, 129091, '<td valign="top">I like this image, nice tones and softness.  Feels like what is going on in my head!</td>', 'I like this image, nice tones and softness.  Feels like what is going on in my head!', '2011-04-10 12:12:46.000000', NULL, 1),
(6381243, 945150, 104230, '<td valign="top">While I think this plaque is hilarious, and might enjoy seeing the item itself hung in an exhibit, I don''t find a photograph of it at all appealing, nor do I consider the photograph to be a contribution to fine art.  Just my personal take on this, of course.</td>', 'While I think this plaque is hilarious, and might enjoy seeing the item itself hung in an exhibit, I don''t find a photograph of it at all appealing, nor do I consider the photograph to be a contribution to fine art.  Just my personal take on this, of course.', '2011-04-10 12:25:49.000000', NULL, 1),
(6381265, 945126, 76335, '<td valign="top">Beautifully composed against the backdrop of light and shape. I wonder if she''s real?</td>', 'Beautifully composed against the backdrop of light and shape. I wonder if she''s real?', '2011-04-10 12:37:09.000000', NULL, 1),
(6381267, 942768, 76335, '<td valign="top">I like the simplicity of this. Might have preferred it in monochrome.</td>', 'I like the simplicity of this. Might have preferred it in monochrome.', '2011-04-10 12:37:41.000000', NULL, 1),
(6381297, 945123, 114225, '<td valign="top">Great use of the Simplify technique.</td>', 'Great use of the Simplify technique.', '2011-04-10 12:54:06.000000', NULL, 1),
(6381302, 944933, 114225, '<td valign="top">Interesting processing. Seems like the foreground is a bit washed out, but it really plays well with the overall scene. I like it.</td>', 'Interesting processing. Seems like the foreground is a bit washed out, but it really plays well with the overall scene. I like it.', '2011-04-10 12:55:58.000000', NULL, 1),
(6381307, 945027, 114225, '<td valign="top">Very cool composition.</td>', 'Very cool composition.', '2011-04-10 12:58:46.000000', NULL, 1),
(6381313, 945187, 114225, '<td valign="top">Those pastel colors are very cool and unexpected.</td>', 'Those pastel colors are very cool and unexpected.', '2011-04-10 13:04:20.000000', NULL, 1),
(6381330, 944173, 129091, '<td valign="top">I''m not sure if this is fine art, but I love what you have done.  The image is mysterious and dream like.  I''m not sure where I would be going if I was to climb the ladder.  Nice work.  It allows me to use my imagination.</td>', 'I''m not sure if this is fine art, but I love what you have done.  The image is mysterious and dream like.  I''m not sure where I would be going if I was to climb the ladder.  Nice work.  It allows me to use my imagination.', '2011-04-10 13:26:23.000000', NULL, 1),
(6381338, 943485, 96751, '<td valign="top">I love the mystery created by the blur.  It is clear she is nude, but in a very tantalizing way; the colors are rich and lovely.</td>', 'I love the mystery created by the blur.  It is clear she is nude, but in a very tantalizing way; the colors are rich and lovely.', '2011-04-10 13:40:21.000000', NULL, 1),
(6381339, 944621, 96751, '<td valign="top">A remembered moment.  LOVE the pastel quality of this image.  The unusual angle and pov are powerful elements, and the bicycle gives us enough detail to help us weave a story.</td>', 'A remembered moment.  LOVE the pastel quality of this image.  The unusual angle and pov are powerful elements, and the bicycle gives us enough detail to help us weave a story.', '2011-04-10 13:41:31.000000', NULL, 1),
(6381341, 944974, 96751, '<td valign="top">Interesting pp''ing.</td>', 'Interesting pp''ing.', '2011-04-10 13:41:54.000000', NULL, 1),
(6381343, 945082, 96751, '<td valign="top">Terrific personification achieved with just adding the title.  Incredibly powerful image.  Looks like you used one of the Topaz nightly or ghostly filters to achieve this look on the trees.  Very cool image.</td>', 'Terrific personification achieved with just adding the title.  Incredibly powerful image.  Looks like you used one of the Topaz nightly or ghostly filters to achieve this look on the trees.  Very cool image.', '2011-04-10 13:43:20.000000', NULL, 1),
(6381344, 945248, 96751, '<td valign="top">I always love me a good flip.  Nicely done.  The man''s reflection is the best.</td>', 'I always love me a good flip.  Nicely done.  The man''s reflection is the best.', '2011-04-10 13:43:50.000000', NULL, 1),
(6381346, 944933, 96751, '<td valign="top">This image has a lot of potential, but is lacking finesse somehow.  The colors are kind of murky and the cows sort of all blend together.  But it''s an interesting grouping, and the sky is killer - I might have tried editing this to b/w.</td>', 'This image has a lot of potential, but is lacking finesse somehow.  The colors are kind of murky and the cows sort of all blend together.  But it''s an interesting grouping, and the sky is killer - I might have tried editing this to b/w.', '2011-04-10 13:45:25.000000', NULL, 1),
(6381347, 945129, 96751, '<td valign="top">Marvelous shadows.</td>', 'Marvelous shadows.', '2011-04-10 13:45:51.000000', NULL, 1),
(6381349, 944960, 96751, '<td valign="top">How funny!!!  I tilted my head to the left when this popped up, as though it were a natural landscape image that had been submitted incorrectly.  In fact, I like it better horizontally!  Gorgeous colors (what an amazing wall).  Nice find.</td>', 'How funny!!!  I tilted my head to the left when this popped up, as though it were a natural landscape image that had been submitted incorrectly.  In fact, I like it better horizontally!  Gorgeous colors (what an amazing wall).  Nice find.', '2011-04-10 13:47:16.000000', NULL, 1),
(6381350, 944985, 96751, '<td valign="top">I''m REALLY love this dof thing and a good use of selective desat.  It''s like the "sold" dot you see at galleries :-)<br/> <br/>This image invites me to look at it longer, which is both good and bad, as I start noticing things, like the extra empty space on the left.  I don''t think this adds to the image (all the interesting stuff is concentrated in a centralized manner), making me visualize a square crop as being a better choice for this image.</td>', 'I''m REALLY love this dof thing and a good use of selective desat.  It''s like the "sold" dot you see at galleries :-) This image invites me to look at it longer, which is both good and bad, as I start noticing things, like the extra empty space on the left.  I don''t think this adds to the image (all the interesting stuff is concentrated in a centralized manner), making me visualize a square crop as being a better choice for this image.', '2011-04-10 13:49:45.000000', NULL, 1),
(6381352, 943621, 96751, '<td valign="top">LOVE the unctuousness of this shot!!!!  Great tones too.</td>', 'LOVE the unctuousness of this shot!!!!  Great tones too.', '2011-04-10 13:50:08.000000', NULL, 1),
(6381356, 944699, 96751, '<td valign="top">Interesting angle on a much-photographed subject.  The tone are terrific and unusual.  Don''t know why, but the soft focus bothers me.  It''s such a rich image, I''d prefer sharper details.</td>', 'Interesting angle on a much-photographed subject.  The tone are terrific and unusual.  Don''t know why, but the soft focus bothers me.  It''s such a rich image, I''d prefer sharper details.', '2011-04-10 13:51:10.000000', NULL, 1),
(6381360, 944965, 96751, '<td valign="top">Although this is in color, it is very reminiscent of <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=54645" rel="nofollow" target="_blank">bspurgeon</a>''s work.  The cross-hatched motion blur is such a delicious technique.</td>', 'Although this is in color, it is very reminiscent of  bspurgeon''s work.  The cross-hatched motion blur is such a delicious technique.', '2011-04-10 13:53:56.000000', NULL, 1),
(6381368, 943177, 96751, '<td valign="top">This has such a 19th Century feel to it (Turner, Constable, etc.).  Lovely to look at.  Wondering if those are fires on the distant mountains, or wayward clouds, sneaking down to earth to sniff at the pine scent.</td>', 'This has such a 19th Century feel to it (Turner, Constable, etc.).  Lovely to look at.  Wondering if those are fires on the distant mountains, or wayward clouds, sneaking down to earth to sniff at the pine scent.', '2011-04-10 13:57:45.000000', NULL, 1),
(6381372, 945213, 96751, '<td valign="top">Nice find.  I like how the moss complements the graffiti.</td>', 'Nice find.  I like how the moss complements the graffiti.', '2011-04-10 13:58:31.000000', NULL, 1),
(6381378, 945187, 96751, '<td valign="top">Ghostly, ethereal, surreal, lovely.  The tones you''ve achieved are splendid, and you processed the rays perfectly.  They''re visible but retail their ephemeral quality.  I like how all the birds are heading in the same direction, although it might have been more visually interesting to have them in a less structured arrangement - something over which you had no control.  Just musing.</td>', 'Ghostly, ethereal, surreal, lovely.  The tones you''ve achieved are splendid, and you processed the rays perfectly.  They''re visible but retail their ephemeral quality.  I like how all the birds are heading in the same direction, although it might have been more visually interesting to have them in a less structured arrangement - something over which you had no control.  Just musing.', '2011-04-10 14:00:50.000000', NULL, 1),
(6381384, 945005, 96751, '<td valign="top">AWESOME portrait!!!!!  Gosh, I''d like to think this could have been one of MY efforts. Even the set looks like my studio :-)<br/> <br/>My only tiny gripe is that the apple is not in focus.  This would ordinarily not be such a bad thing, but because the detail is so magnificent and profound EVERYWHERE else, I find it detracts from this fine image.<br/> <br/>Still, beautiful lighting.  Love how the snake seems to be saying "NOW can I eat???"</td>', 'AWESOME portrait!!!!!  Gosh, I''d like to think this could have been one of MY efforts. Even the set looks like my studio :-) My only tiny gripe is that the apple is not in focus.  This would ordinarily not be such a bad thing, but because the detail is so magnificent and profound EVERYWHERE else, I find it detracts from this fine image. Still, beautiful lighting.  Love how the snake seems to be saying "NOW can I eat???"', '2011-04-10 14:03:56.000000', NULL, 1),
(6381385, 945250, 96751, '<td valign="top">I just got a kitty rush :-)<br/> <br/>Love those tones, and the racing stripes.</td>', 'I just got a kitty rush :-) Love those tones, and the racing stripes.', '2011-04-10 14:04:23.000000', NULL, 1),
(6381387, 945247, 96751, '<td valign="top">Fabulous fracturing and tones.  Love the concept, although I''m not understanding all that empty space above and to the left. Just a bit of a tighter crop off the left (and a tiny bit off the top) would have made me feel this was better balanced.</td>', 'Fabulous fracturing and tones.  Love the concept, although I''m not understanding all that empty space above and to the left. Just a bit of a tighter crop off the left (and a tiny bit off the top) would have made me feel this was better balanced.', '2011-04-10 14:06:44.000000', NULL, 1),
(6381389, 943613, 96751, '<td valign="top">Very cool colors and object - the combo makes my eyes feel funny!</td>', 'Very cool colors and object - the combo makes my eyes feel funny!', '2011-04-10 14:07:20.000000', NULL, 1),
(6381390, 944320, 96751, '<td valign="top">Lovely tones.</td>', 'Lovely tones.', '2011-04-10 14:07:40.000000', NULL, 1),
(6381393, 945168, 96751, '<td valign="top">Nicely caught!  I feel that this is more of a historic image than an artistic one.  The tilt is driving me nuts, and I find the lighting a tad dull, lacking contrast.  These are probably all intentional editing choices, but there you have it :-)</td>', 'Nicely caught!  I feel that this is more of a historic image than an artistic one.  The tilt is driving me nuts, and I find the lighting a tad dull, lacking contrast.  These are probably all intentional editing choices, but there you have it :-)', '2011-04-10 14:09:06.000000', NULL, 1),
(6381395, 942587, 96751, '<td valign="top">Art. Food. Food. Art.  Nice Warhol effort.  Love the light.</td>', 'Art. Food. Food. Art.  Nice Warhol effort.  Love the light.', '2011-04-10 14:09:39.000000', NULL, 1),
(6381397, 945005, 118340, '<td valign="top">Very nice. Plus, I don''t understand it (which makes it art)!</td>', 'Very nice. Plus, I don''t understand it (which makes it art)!', '2011-04-10 14:10:41.000000', NULL, 1),
(6381438, 942666, 16106, '<td valign="top">I would have liked this better without the mirror. The doubled image of the light bouncing between the glass and the mirroring on its backing messes up the purity of form that is so nice in the rocks you picked out. The framing and exposure are very good, but it is such a simple image that the one flaw hurts the image badly.</td>', 'I would have liked this better without the mirror. The doubled image of the light bouncing between the glass and the mirroring on its backing messes up the purity of form that is so nice in the rocks you picked out. The framing and exposure are very good, but it is such a simple image that the one flaw hurts the image badly.', '2011-04-10 14:43:27.000000', NULL, 1),
(6381441, 945063, 16106, '<td valign="top">I can picture this really working well as a large print in a gallery, but shrunk to 800 pixels there just isn''t room to get lost in the frame and wander in the fog.</td>', 'I can picture this really working well as a large print in a gallery, but shrunk to 800 pixels there just isn''t room to get lost in the frame and wander in the fog.', '2011-04-10 14:46:11.000000', NULL, 1),
(6381447, 945176, 96751, '<td valign="top">I definitely see the hand molding the clay.  Very cool.  A bit harsh on the pp''ing though.</td>', 'I definitely see the hand molding the clay.  Very cool.  A bit harsh on the pp''ing though.', '2011-04-10 14:56:28.000000', NULL, 1),
(6381450, 944913, 96751, '<td valign="top">Impressionistic for sure!</td>', 'Impressionistic for sure!', '2011-04-10 14:57:06.000000', NULL, 1),
(6381451, 945201, 96751, '<td valign="top">I just love how this looks like a charcoal drawing :-)</td>', 'I just love how this looks like a charcoal drawing :-)', '2011-04-10 14:57:12.000000', NULL, 1),
(6381454, 944639, 96751, '<td valign="top">Exquisite detail, I just wish it was either more tilted, or more straightened...</td>', 'Exquisite detail, I just wish it was either more tilted, or more straightened...', '2011-04-10 14:57:47.000000', NULL, 1),
(6381456, 944750, 96751, '<td valign="top">I love the optical illusion of the closer person sitting BELOW the waterline, with the water threatening to spill over.  Very cool, gritty image.</td>', 'I love the optical illusion of the closer person sitting BELOW the waterline, with the water threatening to spill over.  Very cool, gritty image.', '2011-04-10 14:58:49.000000', NULL, 1),
(6381457, 945080, 96751, '<td valign="top">Gives me vertigo....  great blur.</td>', 'Gives me vertigo....  great blur.', '2011-04-10 14:59:03.000000', NULL, 1),
(6381458, 945058, 96751, '<td valign="top">This is the first image I''ve come across where I feel it is "art".  I have no idea how to explain why, but there you have it.  Glorious and engaging, full of textures and tones (and a cat).  I have no idea how you did this, with the textures overlapping the subject - and pray it isn''t an overlay!!!!  A fave.  Just gorgeous.</td>', 'This is the first image I''ve come across where I feel it is "art".  I have no idea how to explain why, but there you have it.  Glorious and engaging, full of textures and tones (and a cat).  I have no idea how you did this, with the textures overlapping the subject - and pray it isn''t an overlay!!!!  A fave.  Just gorgeous.', '2011-04-10 15:00:56.000000', NULL, 1),
(6381459, 945020, 96751, '<td valign="top">So pretty and smooth.</td>', 'So pretty and smooth.', '2011-04-10 15:01:24.000000', NULL, 1),
(6381460, 943892, 96751, '<td valign="top">Interesting concept.  I think you had an intriguing idea, which could have been quite provocative, but I feel like you played it safe - in the processing, the shooting angle, etc.</td>', 'Interesting concept.  I think you had an intriguing idea, which could have been quite provocative, but I feel like you played it safe - in the processing, the shooting angle, etc.', '2011-04-10 15:02:48.000000', NULL, 1),
(6381461, 942600, 96751, '<td valign="top">I feel like I know this place, that I''ve been there.  Where is this???<br/> <br/>The tones and textures here are magnificent, as is that bit of blur of her forward foot and skirt.  The tilt is really bugging me.  Nice street shot.</td>', 'I feel like I know this place, that I''ve been there.  Where is this??? The tones and textures here are magnificent, as is that bit of blur of her forward foot and skirt.  The tilt is really bugging me.  Nice street shot.', '2011-04-10 15:04:15.000000', NULL, 1),
(6381465, 945245, 96751, '<td valign="top">There has been quite a run on gas masks lately.... :-)<br/> <br/>I''m not sure how I feel about this image.  It is for sure, very artsy, and the separate elements are all well done - the cabin and the lighting in the bg are very ominous and portentous.  The figure with the strategically placed case is mysterious and a bit alarming.  But the pp''ing doesn''t help me feel that they are connected in any way.  On the contrary, it feels arbitrary to me.</td>', 'There has been quite a run on gas masks lately.... :-) I''m not sure how I feel about this image.  It is for sure, very artsy, and the separate elements are all well done - the cabin and the lighting in the bg are very ominous and portentous.  The figure with the strategically placed case is mysterious and a bit alarming.  But the pp''ing doesn''t help me feel that they are connected in any way.  On the contrary, it feels arbitrary to me.', '2011-04-10 15:06:32.000000', NULL, 1),
(6381467, 943106, 96751, '<td valign="top">Ewwww!<br/> <br/>and<br/> <br/>Cool!!</td>', 'Ewwww! and Cool!!', '2011-04-10 15:06:52.000000', NULL, 1),
(6381469, 944502, 96751, '<td valign="top">Ah, Ben.  This is really wonderful, and a standout in the sea of blurs.  Whatever that technique of yours is, it always produces exceptional tones and textures.  I am always amazed at how I can make out so much detail in your blurs.  (not voting ''cause I know it''s yours)</td>', 'Ah, Ben.  This is really wonderful, and a standout in the sea of blurs.  Whatever that technique of yours is, it always produces exceptional tones and textures.  I am always amazed at how I can make out so much detail in your blurs.  (not voting ''cause I know it''s yours)', '2011-04-10 15:08:07.000000', NULL, 1),
(6381471, 945022, 96751, '<td valign="top">What a sweet little froggy!</td>', 'What a sweet little froggy!', '2011-04-10 15:08:26.000000', NULL, 1),
(6381472, 944160, 96751, '<td valign="top">Oh goodness.  Is this a snake or is it part of an Iris which looks like a snake.  What a very cool whatever.  Just wish it was a bit sharper.</td>', 'Oh goodness.  Is this a snake or is it part of an Iris which looks like a snake.  What a very cool whatever.  Just wish it was a bit sharper.', '2011-04-10 15:09:14.000000', NULL, 1),
(6381476, 942732, 96751, '<td valign="top">Like bicycle racks for boats!  Love this image.  Not voting ''cause I know whose it is.</td>', 'Like bicycle racks for boats!  Love this image.  Not voting ''cause I know whose it is.', '2011-04-10 15:09:45.000000', NULL, 1),
(6381477, 945151, 96751, '<td valign="top">Nice technique to elevate the mundane to the contemplative-worthy.</td>', 'Nice technique to elevate the mundane to the contemplative-worthy.', '2011-04-10 15:10:18.000000', NULL, 1),
(6381478, 945200, 96751, '<td valign="top">Beautiful.</td>', 'Beautiful.', '2011-04-10 15:10:32.000000', NULL, 1),
(6381483, 945249, 101668, '<td valign="top">Exquisit image, beautiful bokeh and great lighting.</td>', 'Exquisit image, beautiful bokeh and great lighting.', '2011-04-10 15:15:02.000000', NULL, 1),
