(6381488, 945156, 96751, '<td valign="top">Yup, I can see this as a giant print on the wall of a cafe by the ocean.  Lovely and evocative.  I can smell the salt.</td>', 'Yup, I can see this as a giant print on the wall of a cafe by the ocean.  Lovely and evocative.  I can smell the salt.', '2011-04-10 15:16:09.000000', NULL, 1),
(6381492, 945083, 96751, '<td valign="top">I cannot for the life of me explain why I love this image so.  Deeply artistic to me, mundane and ordinary and fabulous.</td>', 'I cannot for the life of me explain why I love this image so.  Deeply artistic to me, mundane and ordinary and fabulous.', '2011-04-10 15:17:04.000000', NULL, 1),
(6381495, 944726, 96751, '<td valign="top">I definitely see the hand molding the clay.  Very cool.  A bit harsh on the pp''ing though.</td>', 'I definitely see the hand molding the clay.  Very cool.  A bit harsh on the pp''ing though.', '2011-04-10 15:17:12.000000', NULL, 1),
(6381496, 945256, 96751, '<td valign="top">Groovy.</td>', 'Groovy.', '2011-04-10 15:17:22.000000', NULL, 1),
