(6385744, 945226, 53814, '<td valign="top">I think <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=50695" rel="nofollow" target="_blank">posthumous</a> took this with his left hand while walking his pet beaver. In my top 5 for this challenge.</td>', 'I think  posthumous took this with his left hand while walking his pet beaver. In my top 5 for this challenge.', '2011-04-14 00:20:44.000000', NULL, 1),
(6385749, 945083, 53814, '<td valign="top">The processing fits this universe perfectly. In my top 5 for this challenge.</td>', 'The processing fits this universe perfectly. In my top 5 for this challenge.', '2011-04-14 00:25:27.000000', NULL, 1),
(6385751, 943357, 53814, '<td valign="top">It''s irony to have a fine art contest on DPC - where poems like this are passed by without a second glance. On my third pass through, I''m trying to imagine the photos as if hanging on a gallery wall, and I''m trying to pick the ones that deserve to be there. This one, after a week, is one of the few left hanging.</td>', 'It''s irony to have a fine art contest on DPC - where poems like this are passed by without a second glance. On my third pass through, I''m trying to imagine the photos as if hanging on a gallery wall, and I''m trying to pick the ones that deserve to be there. This one, after a week, is one of the few left hanging.', '2011-04-14 00:25:47.000000', NULL, 1),
(6385759, 944659, 53814, '<td valign="top">A bizarre couple... for some reason I can''t help but wonder about their sex life. Not many photos have that effect on me.<br/>In my top 5 for this challenge.</td>', 'A bizarre couple... for some reason I can''t help but wonder about their sex life. Not many photos have that effect on me.In my top 5 for this challenge.', '2011-04-14 00:37:18.000000', NULL, 1),
