INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6388253, 944659, 65319, '<td valign="top">I googled "American Darling" and I guess the next time someone calls me that...I shouldn''t be flattered at the reference to a hydrant!...;-)  What a quick eye you have to catch the matching reds in color and shape!<br/> <br/>Her facial expression reminds me of Cruella DeVille so I hope you don''t own a dalmatian puppy!  <br/> <br/>The diagonal lines and the patterns of the cinder block wall add to the dimensional impression in the background increased by the diagonal angle, and gives compositional impact to this image.  <br/> <br/>Good work, Brian!</td>', 'I googled "American Darling" and I guess the next time someone calls me that...I shouldn''t be flattered at the reference to a hydrant!...;-)  What a quick eye you have to catch the matching reds in color and shape! Her facial expression reminds me of Cruella DeVille so I hope you don''t own a dalmatian puppy!   The diagonal lines and the patterns of the cinder block wall add to the dimensional impression in the background increased by the diagonal angle, and gives compositional impact to this image.   Good work, Brian!', '2011-04-16 21:15:45.000000', NULL, 0),
(6388283, 943621, 67145, '<td valign="top">WOW .. this is powerful .. :)</td>', 'WOW .. this is powerful .. :)', '2011-04-16 22:11:26.000000', NULL, 0),
(6388295, 945250, 93565, '<td valign="top">Very nice Michelle. I hadn''t picked this one out as yours, but it is a pleasing photo. The coloring gives it a decidedly nostalgic feel, and the crispness alongside the blur is welcomed.</td>', 'Very nice Michelle. I hadn''t picked this one out as yours, but it is a pleasing photo. The coloring gives it a decidedly nostalgic feel, and the crispness alongside the blur is welcomed.', '2011-04-16 22:59:31.000000', NULL, 0),
(6388298, 945187, 70661, '<td valign="top">One of my fav''s! I''m so sorry about the DQ!</td>', 'One of my fav''s! I''m so sorry about the DQ!', '2011-04-16 23:18:01.000000', NULL, 0),
(6388305, 944832, 86447, '<td valign="top">I''m sorry, Jennifer... I really, really don''t like how this makes me feel... <br/> <br/>BUT, it''s very well done.  LOL!<br/></td>', 'I''m sorry, Jennifer... I really, really don''t like how this makes me feel...  BUT, it''s very well done.  LOL!', '2011-04-16 23:26:11.000000', NULL, 0),
