(6388326, 944365, 30982, '<td valign="top">I like this just the way you have it.  I wouldn''t change the crop, the processing - it all works just fine the way it is.  Well done, in my opinion!</td>', 'I like this just the way you have it.  I wouldn''t change the crop, the processing - it all works just fine the way it is.  Well done, in my opinion!', '2011-04-17 01:11:51.000000', NULL, 0),
(6388489, 943892, 23098, '<td valign="top">As I voted on the challenge entries this one always stopped me.  I weighed and considered this powerful image with every pass.  One to remember.</td>', 'As I voted on the challenge entries this one always stopped me.  I weighed and considered this powerful image with every pass.  One to remember.', '2011-04-17 10:49:19.000000', NULL, 0),
